#!/usr/bin/env bash
# @id      kusari-synth-seed
# @doc     docs/EAP/kusari-e2e.md
# @tests   test/acceptance/signals-review.spec.ts
#
# Seed a live signal-ingest with a recent synthetic Kusari CloudTrail-shaped
# stream, so the /signals review page and the Kusari walkthrough have decisions
# to show on a cluster that is not yet pulling from a real queue.
#
# The stream is generated by cmd/kusari-synth (deterministic for a seed) and
# posted with the stun-sentinel key, which writes for tenant kusari. Keys never
# touch argv: curl reads the Authorization header from a 0600 file.
#
# Usage: scripts/kusari-synth-seed.sh [SEED] [MINUTES] [RATE]
#   KUBECONFIG         cluster to seed (required)
#   INGEST_NS          namespace of signal-ingest (default fe-signalloom)
#   SEED_PORT          local port for the port-forward (default 28094)
set -uo pipefail
SEED="${1:-7}"; MINUTES="${2:-30}"; RATE="${3:-4}"
INGEST_NS="${INGEST_NS:-fe-signalloom}"
SEED_PORT="${SEED_PORT:-28094}"
REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
[ -n "${KUBECONFIG:-}" ] && [ "${KUBECONFIG}" != /dev/null ] || { echo "kusari-synth-seed: set KUBECONFIG to the cluster to seed" >&2; exit 2; }
for tool in curl kubectl go base64; do command -v "$tool" >/dev/null || { echo "kusari-synth-seed: need $tool" >&2; exit 2; }; done

hdr=$(mktemp -t kusari-seed.XXXXXX) || exit 2
body=$(mktemp -t kusari-seed-body.XXXXXX) || exit 2
pf=""
cleanup() { [ -n "$pf" ] && kill "$pf" 2>/dev/null; rm -f "$hdr" "$body"; }
trap cleanup EXIT

token=$(kubectl -n "$INGEST_NS" get secret signal-ingest-key-stun-sentinel -o jsonpath='{.data.token}' | base64 -d) || exit 2
[ -n "$token" ] || { echo "kusari-synth-seed: stun-sentinel key is empty" >&2; exit 2; }
( umask 077; printf 'Authorization: Bearer %s\n' "$token" > "$hdr" )

( cd "$REPO_ROOT/d2-signalloom/apps/signal-ingest" && CGO_ENABLED=0 go run ./cmd/kusari-synth -recent -minutes "$MINUTES" -rate "$RATE" -seed "$SEED" ) > "$body" || exit 2

kubectl -n "$INGEST_NS" port-forward svc/signal-ingest "${SEED_PORT}:8082" >/dev/null 2>&1 3>&- &
pf=$!
# The API port authenticates /readyz (the unauthenticated probe lives on the pod's probe
# port, which the Service does not expose), so this gate asks only whether the forward
# answers HTTP at all: any status is a live listener, 000 is not.
ready=0
for _ in $(seq 1 60); do
  code=$(curl -s -o /dev/null -w '%{http_code}' "http://127.0.0.1:${SEED_PORT}/readyz")
  [ "$code" != "000" ] && { ready=1; break; }
  sleep 0.25
done
[ "$ready" = 1 ] || { echo "kusari-synth-seed: signal-ingest not reachable through the port-forward" >&2; exit 3; }

code=$(curl -s -o "$body.out" -w '%{http_code}' -X POST -H @"$hdr" -H 'Content-Type: application/json' --data-binary @"$body" "http://127.0.0.1:${SEED_PORT}/api/v1/observations")
rm -f "$body.out"
case "$code" in
  201) echo "kusari-synth-seed: seed=$SEED minutes=$MINUTES rate=$RATE posted (201)";;
  *)   echo "kusari-synth-seed: POST returned $code" >&2; exit 4;;
esac
